"    // -------------------------------------------------------------------------
    // FIGURE 6: LEARNING CONVERGENCE OVER 2000 TIME SLOTS (DYNAMIC PAPER FIG 6)
    // -------------------------------------------------------------------------
    function drawFig6() {
      const W = cStage.width, H = cStage.height;
      const v = getFormValues();
      const res = computeSystemState(v.bob, v.eve, v.snr, v.alpha, v.delta1, v.delta2);
      const st = getThemeStyles();

      ctx.fillStyle = st.bg;
      ctx.fillRect(0, 0, W, H);

      const numSlots = 2000;
      const numSteps = 120;

      // 1. Dynamic Physical Scaling based on active geometry & channel gains:
      const d_be = res.d_be;
      const distScale = d_be < 0.40 ? Math.max(0, d_be / 0.40) : 1.0;
      const hAB_nom = 1.733e-5;
      const bobGainScale = Math.min(1.25, Math.max(0.60, res.h_AB / hAB_nom));
      const geomScale = distScale * (0.80 + 0.20 * bobGainScale);

      // Theoretical upper bounds (Calibrated to IEEE paper Fig. 6 values at nominal positions)
      // Paper Fig 6 reported values: Bound = 5.75, DRL = 5.68, RL = 5.14, DRL-VB = 4.65, SBJ = 4.65, Robust = 3.65
      const cs_theo = 5.75 * geomScale;
      const cs_drl_final = 5.68 * geomScale;
      const cs_rl_final = 5.14 * geomScale;
      const cs_vb_final = 4.65 * geomScale;
      const cs_sbj_val = 4.65 * geomScale;
      const cs_rob_val = 3.65 * geomScale;

      const cs_drl_init = 3.74 * geomScale;
      const cs_rl_init = 3.64 * geomScale;
      const cs_vb_init = 3.45 * geomScale;

      // (a) Secrecy Rate Convergence
