const ROOM = [5.0, 5.0, 3.0];
const ALICE = [2.5, 2.5, 3.0];
const Ap = 1e-4, R = 0.54, n0 = 1.5, fov = Math.PI / 3.0;
const m_order = 1.0;
const g_conc = (n0 * n0) / (Math.sin(fov) * Math.sin(fov));

function getGain(tx, rx, n_led = 4) {
  const dx = rx[0] - tx[0], dy = rx[1] - tx[1], dz = rx[2] - tx[2];
  const d = Math.sqrt(dx*dx + dy*dy + dz*dz);
  if (d < 1e-7) return 0;
  const cos_phi = (tx[2] - rx[2]) / d;
  const cos_psi = (tx[2] - rx[2]) / d;
  if (cos_phi <= 0 || cos_psi <= 0) return 0;
  const psi = Math.acos(Math.min(1.0, Math.max(-1.0, cos_psi)));
  if (psi > fov) return 0;
  const G = ((m_order + 1.0) * Ap / (2 * Math.PI * d * d)) * Math.pow(cos_phi, m_order) * g_conc * cos_psi;
  return R * n_led * G;
}

