      function getBerVal(s, scheme) {
        const tables = {
          drl:    [2.3e-3, 2.0e-3, 1.8e-3, 1.6e-3, 1.5e-3, 9.0e-4, 5.0e-4, 2.5e-4, 1.0e-4],
