        const idx = Math.floor((s - 4.0) / 2.0);
        const frac = (s - 4.0) / 2.0 - idx;
        const v1 = Math.log10(arr[idx]);
        const v2 = Math.log10(arr[Math.min(8, idx + 1)]);
        return Math.pow(10, v1 + frac * (v2 - v1));
